import { useState } from 'react';
import { Link, Navigate, useNavigate } from 'react-router-dom';
import { getSession, homeForSession, login } from '../auth/auth.js';

/** Render the local demo login form.
 * @returns {JSX.Element} Login page.
 */
export default function LoginPage() {
  const navigate = useNavigate();
  const session = getSession();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  if (session) return <Navigate replace to={homeForSession(session)} />;

  function handleSubmit(event) {
    event.preventDefault();
    const result = login(username.trim(), password);
    if (!result.ok) {
      setError(result.error);
      return;
    }
    navigate(homeForSession(result.session), { replace: true });
  }

  return (
    <main className="flex min-h-[100dvh] items-center justify-center bg-gradient-to-br from-indigo-700 via-violet-700 to-pink-600 px-4 py-12">
      <section aria-labelledby="login-heading" className="w-full max-w-md rounded-3xl bg-white p-7 shadow-2xl sm:p-10">
        <Link className="font-display text-xl font-bold text-slate-900" to="/">Write<span className="text-indigo-600">Space</span></Link>
        <h1 className="mt-8 font-display text-3xl font-bold text-slate-900" id="login-heading">Welcome back</h1>
        <p className="mt-2 text-slate-600">Sign in to read and write.</p>
        <form className="mt-8 space-y-5" onSubmit={handleSubmit}>
          <div>
            <label className="mb-2 block text-sm font-semibold text-slate-700" htmlFor="username">Username</label>
            <input aria-required="true" autoComplete="username" className="w-full rounded-xl border border-slate-300 px-4 py-3 text-slate-900 outline-none transition-shadow focus:border-indigo-600 focus:ring-4 focus:ring-indigo-100" id="username" onChange={(event) => setUsername(event.target.value)} required value={username} />
          </div>
          <div>
            <label className="mb-2 block text-sm font-semibold text-slate-700" htmlFor="password">Password</label>
            <input aria-required="true" autoComplete="current-password" className="w-full rounded-xl border border-slate-300 px-4 py-3 text-slate-900 outline-none transition-shadow focus:border-indigo-600 focus:ring-4 focus:ring-indigo-100" id="password" onChange={(event) => setPassword(event.target.value)} required type="password" value={password} />
          </div>
          {error && <p className="rounded-lg bg-rose-50 px-3 py-2 text-sm font-medium text-rose-800" role="alert">{error}</p>}
          <button className="w-full rounded-full bg-indigo-700 px-5 py-3 font-bold text-white shadow-md transition-transform hover:-translate-y-0.5 hover:bg-indigo-800 active:scale-[0.98]" type="submit">Login</button>
        </form>
        <p className="mt-6 text-center text-sm text-slate-600">New to WriteSpace? <Link className="font-semibold text-indigo-700 hover:underline" to="/register">Register</Link></p>
        <p className="mt-5 rounded-lg bg-slate-50 px-3 py-2 text-center text-xs text-slate-500">Demo admin: username <strong>admin</strong>, password <strong>admin</strong>. Do not use real passwords.</p>
      </section>
    </main>
  );
}

import { useState } from 'react';
import { Link, Navigate, useNavigate } from 'react-router-dom';
import { getSession, homeForSession, register } from '../auth/auth.js';

const fields = [
  { name: 'displayName', label: 'Display Name', type: 'text', autoComplete: 'name' },
  { name: 'username', label: 'Username', type: 'text', autoComplete: 'username' },
  { name: 'password', label: 'Password', type: 'password', autoComplete: 'new-password' },
  { name: 'confirmPassword', label: 'Confirm Password', type: 'password', autoComplete: 'new-password' },
];

/** Render the self-registration form with field-associated validation errors.
 * @returns {JSX.Element} Registration page.
 */
export default function RegisterPage() {
  const navigate = useNavigate();
  const session = getSession();
  const [values, setValues] = useState({ displayName: '', username: '', password: '', confirmPassword: '' });
  const [errors, setErrors] = useState({});
  if (session) return <Navigate replace to={homeForSession(session)} />;

  function handleSubmit(event) {
    event.preventDefault();
    const result = register(values);
    if (!result.ok) {
      setErrors(result.errors);
      return;
    }
    navigate('/blogs', { replace: true });
  }

  return (
    <main className="flex min-h-[100dvh] items-center justify-center bg-gradient-to-br from-indigo-700 via-violet-700 to-pink-600 px-4 py-10">
      <section aria-labelledby="register-heading" className="w-full max-w-lg rounded-3xl bg-white p-7 shadow-2xl sm:p-10">
        <Link className="font-display text-xl font-bold text-slate-900" to="/">Write<span className="text-indigo-600">Space</span></Link>
        <h1 className="mt-7 font-display text-3xl font-bold text-slate-900" id="register-heading">Make room for your words</h1>
        <p className="mt-2 text-slate-600">Create a local account to start writing.</p>
        <form className="mt-7 space-y-4" onSubmit={handleSubmit}>
          {fields.map((field) => (
            <div key={field.name}>
              <label className="mb-2 block text-sm font-semibold text-slate-700" htmlFor={field.name}>{field.label}</label>
              <input
                aria-describedby={errors[field.name] ? `${field.name}-error` : undefined}
                aria-invalid={Boolean(errors[field.name])}
                aria-required="true"
                autoComplete={field.autoComplete}
                className="w-full rounded-xl border border-slate-300 px-4 py-3 text-slate-900 outline-none transition-shadow focus:border-indigo-600 focus:ring-4 focus:ring-indigo-100"
                id={field.name}
                onChange={(event) => setValues((current) => ({ ...current, [field.name]: event.target.value }))}
                required
                type={field.type}
                value={values[field.name]}
              />
              {errors[field.name] && <p className="mt-1 text-sm text-rose-700" id={`${field.name}-error`} role="alert">{errors[field.name]}</p>}
            </div>
          ))}
          {errors.form && <p className="text-sm text-rose-700" role="alert">{errors.form}</p>}
          <button className="w-full rounded-full bg-indigo-700 px-5 py-3 font-bold text-white shadow-md transition-transform hover:-translate-y-0.5 hover:bg-indigo-800 active:scale-[0.98]" type="submit">Create Account</button>
        </form>
        <p className="mt-6 text-center text-sm text-slate-600">Already have an account? <Link className="font-semibold text-indigo-700 hover:underline" to="/login">Login</Link></p>
        <p className="mt-4 text-center text-xs text-slate-500">Demo only. Account data is stored in this browser and passwords are not encrypted.</p>
      </section>
    </main>
  );
}

import { BrowserRouter, Navigate, Route, Routes } from 'react-router-dom';
import LandingPage from './pages/LandingPage.jsx';
import LoginPage from './pages/LoginPage.jsx';
import RegisterPage from './pages/RegisterPage.jsx';
import ProtectedRoute from './components/ProtectedRoute.jsx';

/** Define the single client-side router for WriteSpace.
 * @returns {JSX.Element} Application route tree.
 */
export default function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route element={<LandingPage />} path="/" />
        <Route element={<LoginPage />} path="/login" />
        <Route element={<RegisterPage />} path="/register" />
        <Route element={<ProtectedRoute><div className="p-8">Blog workspace is loading.</div></ProtectedRoute>} path="/blogs" />
        <Route element={<ProtectedRoute role="admin"><div className="p-8">Administrator workspace is loading.</div></ProtectedRoute>} path="/admin" />
        <Route element={<Navigate replace to="/" />} path="*" />
      </Routes>
    </BrowserRouter>
  );
}

import { beforeEach, describe, expect, it, vi } from 'vitest';
import { ADMIN_USER, getSession, homeForSession, login, logout, readStoredArray, register, USERS_KEY } from './auth.js';

beforeEach(() => {
  window.localStorage.clear();
});

describe('local identity helpers', () => {
  it('authenticates the built-in admin and persists an admin session', () => {
    const result = login('admin', 'admin');
    expect(result.ok).toBe(true);
    expect(result.session).toMatchObject({ userId: ADMIN_USER.userId, role: 'admin' });
    expect(getSession()).toEqual(result.session);
    expect(homeForSession(result.session)).toBe('/admin');
  });

  it('rejects invalid credentials with the specified message', () => {
    expect(login('admin', 'wrong')).toEqual({ ok: false, error: 'Invalid username or password.' });
    expect(getSession()).toBeNull();
  });

  it('registers a user, persists the account and session, and logs in after reload', () => {
    const result = register({ displayName: 'Rae Writer', username: 'rae', password: 'secret', confirmPassword: 'secret' });
    expect(result.ok).toBe(true);
    expect(result.session.role).toBe('user');
    expect(JSON.parse(window.localStorage.getItem(USERS_KEY))).toHaveLength(1);
    expect(homeForSession(result.session)).toBe('/blogs');
    window.localStorage.removeItem('writespace_session');
    expect(login('rae', 'secret').ok).toBe(true);
  });

  it('rejects missing fields, mismatched passwords, and the reserved admin username', () => {
    expect(register({ displayName: '', username: '', password: '', confirmPassword: '' }).errors).toMatchObject({
      displayName: 'Display name is required.',
      username: 'That username is already taken.',
      password: 'Password is required.',
      confirmPassword: 'Please confirm your password.',
    });
    expect(register({ displayName: 'Rae', username: 'rae', password: 'one', confirmPassword: 'two' }).errors.confirmPassword).toBe('Passwords do not match.');
    expect(register({ displayName: 'Admin', username: 'ADMIN', password: 'one', confirmPassword: 'one' }).errors.username).toBe('That username is already taken.');
  });

  it('rejects duplicate usernames case-insensitively', () => {
    register({ displayName: 'Rae', username: 'rae', password: 'secret', confirmPassword: 'secret' });
    expect(register({ displayName: 'Another Rae', username: 'RAE', password: 'secret', confirmPassword: 'secret' }).errors.username).toBe('That username is already taken.');
  });

  it('returns an empty array for malformed or unavailable local storage', () => {
    window.localStorage.setItem(USERS_KEY, '{broken');
    expect(readStoredArray(USERS_KEY)).toEqual([]);
